mkdir -p /workspace/tests && cat > /workspace/tests/harness.py <<'PYEOF'
"""Test harness helpers (not part of the submission)."""
import json, subprocess, sys, os

MAIN = '/workspace/submission/main.py'

def run_raw(raw):
    p = subprocess.run([sys.executable, '-I', MAIN], input=raw,
                       capture_output=True, timeout=120)
    return p.returncode, p.stdout, p.stderr

def run(doc):
    raw = doc if isinstance(doc, (bytes, bytearray)) else (
        json.dumps(doc).encode() if not isinstance(doc, str) else doc.encode())
    return run_raw(raw)

ERR = '{"error":"invalid-input"}\n'

class Checks:
    def __init__(self):
        self.fails = 0
        self.count = 0
    def check(self, name, cond, detail=''):
        self.count += 1
        if not cond:
            self.fails += 1
            print('FAIL: %s %s' % (name, detail))
        return cond
    def expect_invalid(self, name, doc):
        rc, out, err = run(doc)
        ok = (rc == 0 and out == ERR.encode() and not err)
        return self.check(name, ok, 'rc=%r out=%r err=%r' % (rc, out[:200], err[:300]))
    def expect_valid(self, name, doc):
        rc, out, err = run(doc)
        if rc != 0 or not out.endswith(b'\n'):
            return self.check(name, False, 'rc=%r out=%r err=%r' % (rc, out[:300], err[:400]))
        try:
            parsed = json.loads(out)
        except Exception as exc:
            return self.check(name, False, 'json decode failed: %r %r' % (exc, out[:200]))
        if set(parsed) != {'runs','audits','diagnostic'}:
            return self.check(name, False, 'root keys %r' % (set(parsed),))
        return parsed
    def done(self, label):
        print('%s: %d checks, %d failures' % (label, self.count, self.fails))
        return self.fails

def base(zones=None, profiles=None, queries=None, observations=None,
         zones_override=None):
    doc = {
        'zones': zones if zones is not None else [],
        'profiles': profiles if profiles is not None else
            [{'id': 'p', 'max_aliases': 4, 'cname': 'follow', 'wildcard': 'rfc'}],
        'queries': queries if queries is not None else [],
        'observations': observations if observations is not None else [],
    }
    if zones_override is not None:
        doc['zones'] = zones_override
    return doc

def prof(pid='p', ma=4, cname='follow', wildcard='rfc'):
    return {'id': pid, 'max_aliases': ma, 'cname': cname, 'wildcard': wildcard}

def query(qid, name, rtype='A', cost=1):
    return {'id': qid, 'name': name, 'type': rtype, 'cost': cost}

def rec(owner, rtype, data):
    return {'owner': owner, 'type': rtype, 'data': data}
